document.querySelector('.menu-toggle')?.addEventListener('click',function(){const n=document.querySelector('nav');const o=n.classList.toggle('open');this.setAttribute('aria-expanded',String(o))});document.querySelector('#quote-form')?.addEventListener('submit',function(e){e.preventDefault();if(!this.reportValidity())return;const d=new FormData(this);const body=[...d.entries()].map(([k,v])=>k+': '+v).join('\n');document.querySelector('#email-draft').href='mailto:hello@citruscustomapparel.com?subject='+encodeURIComponent('Custom apparel quote: '+d.get('Name'))+'&body='+encodeURIComponent(body);document.querySelector('#quote-result').hidden=false;document.querySelector('#email-draft').focus()});